// hello.rs
// puts 是系统提供的“打印一行字符串”函数。
unsafe extern "C" {
    fn puts(text: *const core::ffi::c_char) -> core::ffi::c_int;
}

#[unsafe(no_mangle)]
#[inline(never)]
pub extern "C" fn hello() {
    // SAFETY: c"..." 提供有效、以零结尾的字符串，puts 只在调用期间读取它。
    unsafe {
        puts(c"Hello, world!".as_ptr());
    }
}

// main.rs

#[cfg(not(xollvm))]
mod hello;

#[cfg(xollvm)]
unsafe extern "C" {
    fn hello();
}

fn main() {
    #[cfg(not(xollvm))]
    hello::hello();

    #[cfg(xollvm)]
    // SAFETY: 链接的 hello 来自本示例，没有参数或调用前提。
    unsafe {
        hello();
    }
}

